require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}oecrm_require_csrf();$action=$_POST['action']??'';$companyId=oecrm_current_company_id($conn);$actor=(int)$_SESSION['adminId'];function oecrm_next_client_code($conn,$companyId){$prefix='CL-'.str_pad($companyId,2,'0',STR_PAD_LEFT).'-'.date('Ym').'-';$row=mysqli_fetch_assoc(mysqli_query($conn,"SELECT client_code FROM clients WHERE company_id=".(int)$companyId." AND client_code LIKE '".$prefix."%' ORDER BY id DESC LIMIT 1"));$next=1;if(!empty($row['client_code'])&&preg_match('/-(\\d+)$/',$row['client_code'],$match))$next=(int)$match[1]+1;return $prefix.str_pad($next,4,'0',STR_PAD_LEFT);}try{if($action==='archive_client'){$clientId=(int)($_POST['client_id']??0);oecrm_require_permission($conn,'clients','delete');$client=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM clients WHERE id='.$clientId.' AND company_id='.$companyId));if(!$client)throw new RuntimeException('Client not found.');$active=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COUNT(*) total FROM projectstbl WHERE client_id='.$clientId.' AND company_id='.$companyId.' AND status NOT IN ("completed","cancel")'));$status=(int)$active['total']?'on_hold':'inactive';mysqli_query($conn,"UPDATE clients SET status='$status' WHERE id=$clientId AND company_id=$companyId");oecrm_audit($conn,'clients','archive','client',$clientId,'Client archived with dependency check',$client,['status'=>$status,'active_projects'=>$active['total']]);$_SESSION['client_flash']=(int)$active['total']?'Client has active projects and was placed on hold.':'Client archived successfully.';header('Location: clients.php');exit;}if($action==='save_client'){$id=(int)($_POST['id']??0);oecrm_require_permission($conn,'clients',$id?'edit':'create');$display=trim($_POST['display_name']??'');$legal=trim($_POST['legal_name']??'');$type=$_POST['client_type']??'company';$status=$_POST['status']??'active';if($display===''||$legal==='')throw new RuntimeException('Client names are required.');$fields=['industry','website','email','phone','billing_address','city','state','country','tax_id','notes'];foreach($fields as $f)$$f=trim($_POST[$f]??'');$currency=strtoupper(substr(trim($_POST['currency_code']??'INR'),0,3));$terms=max(0,(int)($_POST['payment_terms_days']??0));if($id){$old=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM clients WHERE id='.(int)$id.' AND company_id='.(int)$companyId));if(!$old)throw new RuntimeException('Client not found.');$code=$old['client_code'];$s=mysqli_prepare($conn,'UPDATE clients SET client_code=?,legal_name=?,display_name=?,client_type=?,status=?,industry=?,website=?,email=?,phone=?,billing_address=?,city=?,state=?,country=?,tax_id=?,currency_code=?,payment_terms_days=?,notes=? WHERE id=? AND company_id=?');mysqli_stmt_bind_param($s,'sssssssssssssssisii',$code,$legal,$display,$type,$status,$industry,$website,$email,$phone,$billing_address,$city,$state,$country,$tax_id,$currency,$terms,$notes,$id,$companyId);}else{$old=null;$code=oecrm_next_client_code($conn,$companyId);$s=mysqli_prepare($conn,'INSERT INTO clients(company_id,client_code,legal_name,display_name,client_type,status,industry,website,email,phone,billing_address,city,state,country,tax_id,currency_code,payment_terms_days,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'isssssssssssssssisi',$companyId,$code,$legal,$display,$type,$status,$industry,$website,$email,$phone,$billing_address,$city,$state,$country,$tax_id,$currency,$terms,$notes,$actor);}mysqli_stmt_execute($s);if(!$id)$id=mysqli_insert_id($conn);mysqli_stmt_close($s);oecrm_audit($conn,'clients',$old?'update':'create','client',$id,'Client profile saved',$old,['client_code'=>$code,'display_name'=>$display,'status'=>$status]);$_SESSION['client_flash']='Client saved successfully.';header('Location: clientProfile.php?id='.$id);exit;}$clientId=(int)($_POST['client_id']??0);$check=mysqli_fetch_assoc(mysqli_query($conn,'SELECT id FROM clients WHERE id='.(int)$clientId.' AND company_id='.(int)$companyId));if(!$check)throw new RuntimeException('Client not found.');if($action==='contact'){oecrm_require_permission($conn,'client_contacts','create');$name=trim($_POST['name']??'');$designation=trim($_POST['designation']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$primary=isset($_POST['is_primary'])?1:0;if($name==='')throw new RuntimeException('Contact name is required.');if($primary)mysqli_query($conn,'UPDATE client_contacts SET is_primary=0 WHERE client_id='.(int)$clientId);$s=mysqli_prepare($conn,'INSERT INTO client_contacts(client_id,name,designation,email,phone,is_primary) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'issssi',$clientId,$name,$designation,$email,$phone,$primary);mysqli_stmt_execute($s);$id=mysqli_insert_id($conn);mysqli_stmt_close($s);oecrm_audit($conn,'client_contacts','create','client_contact',$id,'Client contact added',null,['client_id'=>$clientId,'name'=>$name]);}
elseif($action==='contract'){oecrm_require_permission($conn,'client_contracts','create');$type=$_POST['contract_type']??'service';$title=trim($_POST['title']??'');$start=$_POST['start_date']?:null;$end=$_POST['end_date']?:null;$value=(float)($_POST['value_amount']??0);if($title==='')throw new RuntimeException('Contract title is required.');$s=mysqli_prepare($conn,'INSERT INTO client_contracts(client_id,contract_type,title,start_date,end_date,value_amount,currency_code,status,created_by) VALUES(?,?,?,?,?,?,"INR","active",?)');mysqli_stmt_bind_param($s,'issssdi',$clientId,$type,$title,$start,$end,$value,$actor);mysqli_stmt_execute($s);$id=mysqli_insert_id($conn);mysqli_stmt_close($s);oecrm_audit($conn,'client_contracts','create','client_contract',$id,'Client contract added',null,['client_id'=>$clientId,'title'=>$title]);}
elseif($action==='communication'){oecrm_require_permission($conn,'client_communications','create');$type=$_POST['communication_type']??'note';$subject=trim($_POST['subject']??'');$details=trim($_POST['details']??'');$at=str_replace('T',' ',$_POST['communication_at']??'');if($subject===''||!strtotime($at))throw new RuntimeException('Communication subject and date are required.');$s=mysqli_prepare($conn,'INSERT INTO client_communications(client_id,communication_type,subject,details,communication_at,created_by) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'issssi',$clientId,$type,$subject,$details,$at,$actor);mysqli_stmt_execute($s);$id=mysqli_insert_id($conn);mysqli_stmt_close($s);oecrm_audit($conn,'client_communications','create','client_communication',$id,'Client communication recorded',null,['client_id'=>$clientId,'type'=>$type,'subject'=>$subject]);}
elseif($action==='document'){oecrm_require_permission($conn,'client_documents','upload');$type=$_POST['document_type']??'other';$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Document title is required.');$stored=oecrm_safe_upload($_FILES['document']??null,__DIR__.'/../storage/client_documents',['pdf','doc','docx','jpg','jpeg','png']);$original=$_FILES['document']['name']??'';$mime=$_FILES['document']['type']??'';$size=(int)($_FILES['document']['size']??0);$s=mysqli_prepare($conn,'INSERT INTO client_documents(client_id,document_type,title,stored_name,original_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'isssssii',$clientId,$type,$title,$stored,$original,$mime,$size,$actor);mysqli_stmt_execute($s);$id=mysqli_insert_id($conn);mysqli_stmt_close($s);oecrm_audit($conn,'client_documents','upload','client_document',$id,'Client document uploaded',null,['client_id'=>$clientId,'type'=>$type]);}else throw new RuntimeException('Invalid action.');$_SESSION['client_flash']='Client information updated.';header('Location: clientProfile.php?id='.$clientId);exit;}catch(Throwable $e){$_SESSION['client_error']=$e->getMessage();header('Location: '.(!empty($clientId)?'clientProfile.php?id='.$clientId:'clients.php'));exit;}
